icant.name, passportNumber: passportNumber, purpose: applicant.purpose, validFrom: generateRandomDate(new Date(gameState.currentDate.getTime() - 10 * 86400000), gameState.currentDate), validUntil: generateRandomDate(gameState.currentDate, new Date(gameState.currentDate.getTime() + 20 * 86400000)) }; break; } } if (Math.random() < 0.4 + (gameState.day * 0.025)) introduceDiscrepancy(applicant); checkApplicantAgainstRules(applicant); gameState.currentApplicant = applicant; displayApplicant(applicant); }
